 const filteredModules=useMemo(()=>modules.filter(m=>`${m.name} ${m.description}`.toLowerCase().includes(query.toLowerCase())&&(filter==='All modules'||m.status===filter)),[query,filter]);
 const simScenarios=scenarios.filter(s=>s.module===simModule||simModule==='fire'&&s.module==='risk');
 const startTraining=(scenario:Scenario)=>{setSelectedScenario(scenario);setTrainingStep(0);setFound([]);setFeedback('');setHint(false);setPage('training');setDetail(false);window.scrollTo({top:0,behavior:'smooth'});};
 const navItems:[Page,string,typeof Activity][]=[['home',t('home'),Activity],['modules',t('modules'),Shield],['training',t('training'),Target],['simulator',t('simulator'),Gauge],['safety-game','Safety Game',Award],['progress',t('progress'),Award]];
 const imgStyle=(id:string)=>({backgroundImage:`linear-gradient(90deg, rgba(8,15,21,.88) 0%,rgba(8,15,21,.57) 52%,rgba(8,15,21,.2) 100%),url(${image(id)})`});
